metadata.er-schema:
{
  "title": "looply · 类目管理（Collection）实体关系图",
  "version": "v1.8 · 2026-06-30",
  "tables": [
    {
      "name": "collection",
      "comment": "前台商品分组",
      "columns": [
        {
          "name": "collection_id",
          "comment": "分组ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "title",
          "comment": "前台标题(分端JSON)",
          "constraint": ""
        },
        {
          "name": "subtitle",
          "comment": "页面副标题(分端JSON)",
          "constraint": ""
        },
        {
          "name": "title_color",
          "comment": "标题色值(分端JSON·hex·必填·默认#070707)",
          "constraint": ""
        },
        {
          "name": "subtitle_color",
          "comment": "副标题色值(分端JSON·hex·必填·默认#070707)",
          "constraint": ""
        },
        {
          "name": "url_slug",
          "comment": "URL路径段(不分端)",
          "constraint": "UNIQUE"
        },
        {
          "name": "market_id",
          "comment": "市场（单选）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "channel_id",
          "comment": "渠道（单选）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "banner_url",
          "comment": "Banner图URL(分端JSON)",
          "constraint": ""
        },
        {
          "name": "banner_enabled",
          "comment": "是否展示Banner",
          "constraint": ""
        },
        {
          "name": "seo_title",
          "comment": "Meta Title",
          "constraint": ""
        },
        {
          "name": "seo_description",
          "comment": "Meta Desc",
          "constraint": ""
        },
        {
          "name": "source_type",
          "comment": "选品类型 rule/manual",
          "constraint": ""
        },
        {
          "name": "rule_config",
          "comment": "自动选品规则JSON(brand作为普通条件)",
          "constraint": ""
        },
        {
          "name": "default_sort_key",
          "comment": "默认排序(无manual项)",
          "constraint": ""
        },
        {
          "name": "visual_filter_enabled",
          "comment": "图文筛模块开关",
          "constraint": ""
        },
        {
          "name": "quick_filter_enabled",
          "comment": "移动端快筛模块开关",
          "constraint": ""
        },
        {
          "name": "products_per_page",
          "comment": "PC每页商品数(移动端固定20/屏)",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态 draft/active/closed",
          "constraint": ""
        },
        {
          "name": "sort_order",
          "comment": "排序权重",
          "constraint": ""
        },
        {
          "name": "is_system",
          "comment": "是否系统级",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "is_system=TRUE 为系统级（All Products），不可删除/下架；不区分终端，title/subtitle/title_color/subtitle_color/banner_url 按 PC+移动端两端分端 JSON 存储；title_color/subtitle_color 为 hex 视觉配置(必填、非翻译文本、默认 #070707)；价格筛选范围运行时按商品池动态生成，不入库"
    },
    {
      "name": "fc_manual_product",
      "comment": "手动选品关联",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "collection_id",
          "comment": "所属分组",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "listing_id",
          "comment": "商品listingID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "sort_order",
          "comment": "位置（Position）",
          "constraint": ""
        },
        {
          "name": "pinned",
          "comment": "是否固定位置",
          "constraint": ""
        },
        {
          "name": "is_hidden",
          "comment": "是否隐藏",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "添加时间",
          "constraint": ""
        }
      ],
      "note": "UNIQUE(collection_id, listing_id)；商品下架后保留记录，is_hidden 可临时隐藏；pinned 标记固定位置"
    },
    {
      "name": "fc_hidden_product",
      "comment": "自动选品排除记录",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "collection_id",
          "comment": "所属分组",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "listing_id",
          "comment": "被排除的listingID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "created_at",
          "comment": "排除时间",
          "constraint": ""
        }
      ],
      "note": "UNIQUE(collection_id, listing_id)；自动选品下用于排除单个商品"
    },
    {
      "name": "fc_auto_pin",
      "comment": "自动选品Pin位置",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "collection_id",
          "comment": "所属分组",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "listing_id",
          "comment": "被固定的listingID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "position",
          "comment": "固定位置",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "固定时间",
          "constraint": ""
        }
      ],
      "note": "UNIQUE(collection_id, listing_id)；自动选品支持固定位置，商品下架移出时同步清除pin记录"
    },
    {
      "name": "filter_dimension",
      "comment": "筛选维度（全局池）",
      "columns": [
        {
          "name": "dimension_id",
          "comment": "维度ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "dimension_name",
          "comment": "维度名称(EN,全局唯一)",
          "constraint": ""
        },
        {
          "name": "source_type",
          "comment": "数据源 attribute/brand/series/price/condition/backend_category/tag",
          "constraint": ""
        },
        {
          "name": "source_config",
          "comment": "数据源配置JSON（类目各级展示名等）",
          "constraint": ""
        },
        {
          "name": "display_type_visual",
          "comment": "图文筛展示样式 card/color",
          "constraint": ""
        },
        {
          "name": "display_type_quick",
          "comment": "快筛展示样式 card/panel/slider/color/tree",
          "constraint": ""
        },
        {
          "name": "display_type_common",
          "comment": "通用筛展示样式 card/panel/slider/color/tree",
          "constraint": ""
        },
        {
          "name": "sort_strategy",
          "comment": "排序策略 source/numeric/alpha/count_desc",
          "constraint": ""
        },
        {
          "name": "value_pins",
          "comment": "打平态固定位JSON{值key:位置}",
          "constraint": ""
        },
        {
          "name": "value_order_grouped",
          "comment": "分组态固定位JSON(按属性值全局位次,尺码按体系)",
          "constraint": ""
        },
        {
          "name": "scope_grouped",
          "comment": "仅attribute:是否按作用域分组(默认FALSE)",
          "constraint": ""
        },
        {
          "name": "category_pins",
          "comment": "仅backend_category:类目顺序Pin记录JSON",
          "constraint": ""
        },
        {
          "name": "sort_order",
          "comment": "通用筛选器全局展示顺序",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态 active/inactive",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "source_type=attribute 时经 filter_dimension_source 关联属性；展示样式按图文筛/快筛/通用筛三模块分别配置；枚举值排序=策略+固定位置，打平态(value_pins)与分组态(value_order_grouped)两套独立存储"
    },
    {
      "name": "filter_dimension_source",
      "comment": "维度-属性多源绑定",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "dimension_id",
          "comment": "所属筛选维度",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "attribute_id",
          "comment": "关联属性定义ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "priority",
          "comment": "多源优先级",
          "constraint": ""
        }
      ],
      "note": "UNIQUE(dimension_id, attribute_id)；仅 source_type=attribute 的维度使用"
    },
    {
      "name": "fc_quick_filter",
      "comment": "移动端快筛项配置",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "collection_id",
          "comment": "所属分组",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "dimension_id",
          "comment": "引用的筛选维度",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "sort_order",
          "comment": "从左到右顺序",
          "constraint": ""
        },
        {
          "name": "enabled",
          "comment": "是否展示",
          "constraint": ""
        }
      ],
      "note": "UNIQUE(collection_id, dimension_id)；快筛每项引用一个筛选维度；仅移动端、无适用终端字段；模块总开关在 collection.quick_filter_enabled"
    },
    {
      "name": "fc_visual_filter",
      "comment": "移动端图文筛项配置",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "collection_id",
          "comment": "所属分组",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "label_text",
          "comment": "展示文案",
          "constraint": ""
        },
        {
          "name": "image_enable",
          "comment": "是否展示图片(选项级)",
          "constraint": ""
        },
        {
          "name": "image_url",
          "comment": "图片URL(单图,移动端)",
          "constraint": ""
        },
        {
          "name": "filter_condition",
          "comment": "筛选项JSON（维度AND·同维度多值OR）",
          "constraint": ""
        },
        {
          "name": "sort_order",
          "comment": "排序",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态 active/inactive",
          "constraint": ""
        }
      ],
      "note": "每项=展示文案+图片+一组筛选项(filter_condition)；仅移动端、无适用终端字段;image_enable 选项级图片开关、单张 image_url;维度间AND、同维度多值OR,不支持OR组合/嵌套;无系统级All项"
    },
    {
      "name": "fc_sort_config",
      "comment": "Collection排序项配置",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "collection_id",
          "comment": "所属分组",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "sort_key",
          "comment": "排序项key",
          "constraint": ""
        },
        {
          "name": "sort_order",
          "comment": "展示顺序",
          "constraint": ""
        },
        {
          "name": "is_default",
          "comment": "是否默认排序",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态 active/inactive",
          "constraint": ""
        }
      ],
      "note": "UNIQUE(collection_id, sort_key)；决定本 Collection 展示哪些排序项(recommended/newest/price↑↓)、顺序及默认项；v0.14 起移除 manual 项,固定位置由 Pin 承载"
    },
    {
      "name": "listing",
      "comment": "商品上架记录",
      "columns": [
        {
          "name": "listing_id",
          "comment": "（商品系统）",
          "constraint": "PRIMARY KEY"
        }
      ],
      "note": "外部引用，字段由商品系统维护，不在本模块展开"
    },
    {
      "name": "attribute_def",
      "comment": "属性定义",
      "columns": [
        {
          "name": "attribute_id",
          "comment": "（商品系统）",
          "constraint": "PRIMARY KEY"
        }
      ],
      "note": "外部引用，字段由商品系统维护，不在本模块展开"
    },
    {
      "name": "brand",
      "comment": "品牌",
      "columns": [
        {
          "name": "brand_id",
          "comment": "（商品系统）",
          "constraint": "PRIMARY KEY"
        }
      ],
      "note": "filter_dimension source_type=brand 的数据来源；也作为 rule_config 选品规则中的普通条件字段（逻辑引用）"
    },
    {
      "name": "series",
      "comment": "系列",
      "columns": [
        {
          "name": "series_id",
          "comment": "（商品系统）",
          "constraint": "PRIMARY KEY"
        }
      ],
      "note": "filter_dimension source_type=series 时的数据来源（逻辑引用）"
    },
    {
      "name": "market",
      "comment": "市场",
      "columns": [
        {
          "name": "market_id",
          "comment": "（商品系统）",
          "constraint": "PRIMARY KEY"
        }
      ],
      "note": "collection.market_id 引用，控制商品池范围（逻辑引用）"
    },
    {
      "name": "channel",
      "comment": "渠道",
      "columns": [
        {
          "name": "channel_id",
          "comment": "（商品系统）",
          "constraint": "PRIMARY KEY"
        }
      ],
      "note": "collection.channel_id 引用，读商品中心渠道管理（逻辑引用）"
    },
    {
      "name": "backend_category",
      "comment": "后台类目",
      "columns": [
        {
          "name": "category_id",
          "comment": "（商品系统）",
          "constraint": "PRIMARY KEY"
        }
      ],
      "note": "既作为 filter_dimension 数据源(source_type=backend_category)，也用于 rule_config 条件字段（均为逻辑引用，非FK）"
    },
    {
      "name": "tag",
      "comment": "标签",
      "columns": [
        {
          "name": "tag_id",
          "comment": "（商品系统）",
          "constraint": "PRIMARY KEY"
        }
      ],
      "note": "filter_dimension source_type=tag 时的数据来源；仅取适用对象=渠道商品/通用且启用的标签（逻辑引用）"
    }
  ],
  "relations": [
    {
      "from": "collection",
      "to": "fc_manual_product",
      "type": "1:N",
      "label": "手动选品",
      "color": "#2D72B8",
      "penwidth": 1.8
    },
    {
      "from": "collection",
      "to": "fc_hidden_product",
      "type": "1:N",
      "label": "排除记录",
      "color": "#2D72B8",
      "penwidth": 1.4
    },
    {
      "from": "collection",
      "to": "fc_auto_pin",
      "type": "1:N",
      "label": "自动选品Pin",
      "color": "#2D72B8",
      "penwidth": 1.4
    },
    {
      "from": "collection",
      "to": "fc_quick_filter",
      "type": "1:N",
      "label": "快筛配置",
      "color": "#2D72B8",
      "penwidth": 1.4
    },
    {
      "from": "collection",
      "to": "fc_visual_filter",
      "type": "1:N",
      "label": "图文筛配置",
      "color": "#2D72B8",
      "penwidth": 1.4
    },
    {
      "from": "collection",
      "to": "fc_sort_config",
      "type": "1:N",
      "label": "排序配置",
      "color": "#2D72B8",
      "penwidth": 1.4
    },
    {
      "from": "filter_dimension",
      "to": "fc_quick_filter",
      "type": "1:N",
      "label": "被快筛引用",
      "color": "#2E7D4F",
      "penwidth": 1.4
    },
    {
      "from": "filter_dimension",
      "to": "fc_visual_filter",
      "type": "",
      "label": "filter_condition 引用\n（JSON，非FK）",
      "color": "#BDBDBD",
      "penwidth": 0.8,
      "style": "dashed"
    },
    {
      "from": "filter_dimension",
      "to": "filter_dimension_source",
      "type": "1:N",
      "label": "多源绑定",
      "color": "#2E7D4F",
      "penwidth": 1.4
    },
    {
      "from": "listing",
      "to": "fc_manual_product",
      "type": "1:N",
      "label": "FK",
      "color": "#9E9E9E",
      "penwidth": 1.0
    },
    {
      "from": "listing",
      "to": "fc_hidden_product",
      "type": "1:N",
      "label": "FK",
      "color": "#9E9E9E",
      "penwidth": 1.0
    },
    {
      "from": "listing",
      "to": "fc_auto_pin",
      "type": "1:N",
      "label": "FK",
      "color": "#9E9E9E",
      "penwidth": 1.0
    },
    {
      "from": "attribute_def",
      "to": "filter_dimension_source",
      "type": "1:N",
      "label": "FK",
      "color": "#9E9E9E",
      "penwidth": 1.0
    },
    {
      "from": "brand",
      "to": "filter_dimension",
      "type": "",
      "label": "source_type=brand",
      "color": "#BDBDBD",
      "penwidth": 0.8,
      "style": "dashed"
    },
    {
      "from": "series",
      "to": "filter_dimension",
      "type": "",
      "label": "source_type=series",
      "color": "#BDBDBD",
      "penwidth": 0.8,
      "style": "dashed"
    },
    {
      "from": "backend_category",
      "to": "filter_dimension",
      "type": "",
      "label": "source_type=backend_category",
      "color": "#BDBDBD",
      "penwidth": 0.8,
      "style": "dashed"
    },
    {
      "from": "tag",
      "to": "filter_dimension",
      "type": "",
      "label": "source_type=tag",
      "color": "#BDBDBD",
      "penwidth": 0.8,
      "style": "dashed"
    },
    {
      "from": "backend_category",
      "to": "collection",
      "type": "",
      "label": "rule_config 条件字段\n（JSON引用，非FK）",
      "color": "#BDBDBD",
      "penwidth": 0.8,
      "style": "dashed"
    },
    {
      "from": "market",
      "to": "collection",
      "type": "",
      "label": "market_id",
      "color": "#BDBDBD",
      "penwidth": 0.8,
      "style": "dashed"
    },
    {
      "from": "channel",
      "to": "collection",
      "type": "",
      "label": "channel_id",
      "color": "#BDBDBD",
      "penwidth": 0.8,
      "style": "dashed"
    }
  ],
  "design_rules": {
    "R-01": "Collection 无层级嵌套，扁平结构，导航层级由 Navigation 模块承载",
    "R-02": "商品粒度为 listing 级别，不按 SPU 聚合",
    "R-03": "自动选品/手动选品两种模式互斥（source_type=rule 或 manual）",
    "R-04": "All Products 为系统级 Collection（is_system=TRUE），不可删除、不可下架、rule_config 为空（全量）",
    "R-05": "自动选品支持固定位置（fc_auto_pin）；商品因下架移出 Collection 时同步清除对应 pin 记录",
    "R-06": "手动选品商品下架后 fc_manual_product 记录保留，is_hidden=TRUE，商品重新上架后恢复",
    "R-07": "backend_category 既可作为 filter_dimension 的 source_type，也用于 rule_config 条件字段",
    "R-08": "filter_dimension source_type=attribute 时，通过 filter_dimension_source 支持多个 attribute_def 绑定到同一维度（尺码亦走 attribute）",
    "R-09": "Collection 不区分终端：title/subtitle/banner_url 按 PC+移动端两端分端 JSON 存储；商品来源/市场/渠道/URL/Meta/排序/通用筛选器不分端",
    "R-10": "图文筛、快筛均为移动端专属:PC 端无图文筛栏/快筛栏形态,二者仅移动端、不分端、无适用终端字段;图文筛 image_enable 选项级图片开关、单张 image_url",
    "R-11": "某维度在当前商品池(全集∩图文筛∩搜索词)内有≥2个不同值时才展示，否则前端物理隐藏；count=0 的候选值不返回",
    "R-12": "展示样式 5 种(card/panel/slider/color/tree)，按图文筛/快筛/通用筛三模块分别配置(display_type_*)；可选样式=数据源允许∩模块支持。数据源可用样式：brand/series/condition/tag=card/panel，price=slider，backend_category=tree(固定)，attribute=card/panel(+color仅color_family,+tree仅开启作用域分组)",
